namespace MatchLens.Contracts;

/// <summary>
/// One synthetic match event (schema 1.0). Generated by Match Forge, consumed by the analytics engine.
/// </summary>
/// <remarks>
/// Coordinates are in the acting team's frame: X runs 0..100 from that team's own goal line to the opponent's,
/// Y runs 0..100 across the pitch as that team attacks. The pitch is 105 x 68 m (see <see cref="Pitch"/>).
/// Optional fields are omitted from JSON when not relevant to the event type.
/// </remarks>
public sealed record MatchEvent
{
    public const string SchemaVersion = "1.0";

    /// <summary>Stable id, e.g. "evt-000104". Insights cite these as evidence.</summary>
    public required string EventId { get; init; }

    public required string MatchId { get; init; }

    /// <summary>1-based order within the match. Strictly increasing.</summary>
    public required int Seq { get; init; }

    /// <summary>1 or 2.</summary>
    public required int Period { get; init; }

    /// <summary>
    /// Seconds since kick-off. Never decreases: the second half starts at 2700 (45:00) or, after first-half
    /// stoppage time, a little later.
    /// </summary>
    public required int MatchClockSec { get; init; }

    public required MatchEventType Type { get; init; }

    /// <summary>The team performing the event (for possession changes: the team that gained the ball).</summary>
    public required string TeamId { get; init; }

    public string? PlayerId { get; init; }

    public PitchPoint? Start { get; init; }

    /// <summary>Pass target, or null.</summary>
    public PitchPoint? End { get; init; }

    public EventOutcome? Outcome { get; init; }

    /// <summary>Intended receiver of a pass.</summary>
    public string? RecipientId { get; init; }

    public bool? UnderPressure { get; init; }

    /// <summary>Expected goals of a shot, 0..1.</summary>
    public double? Xg { get; init; }

    public ShotResult? ShotResult { get; init; }

    /// <summary>Ball speed for passes and shots, km/h.</summary>
    public double? BallSpeedKmh { get; init; }

    /// <summary>Set on passes the provider marks as long balls (long and usually lofted, hit over the midfield).</summary>
    public bool? LongBall { get; init; }

    /// <summary>Set when a pass or shot restarts play from a set piece (corner, free kick, penalty).</summary>
    public SetPiece? SetPiece { get; init; }
}

public enum SetPiece
{
    Corner,
    FreeKick,
    Penalty,
}

public enum MatchEventType
{
    PeriodStart,
    PeriodEnd,
    KickOff,
    Pass,
    Shot,
    Goal,
    Pressure,
    Tackle,
    Interception,
    PossessionChange,
    Foul,
    Card,
    Substitution,
}

public enum EventOutcome
{
    Success,
    Fail,
}

public enum ShotResult
{
    Goal,
    Saved,
    OffTarget,
    Blocked,
}

/// <summary>A point in the acting team's frame, both axes 0..100.</summary>
public readonly record struct PitchPoint(double X, double Y);

public static class Pitch
{
    public const double LengthMetres = 105;
    public const double WidthMetres = 68;

    /// <summary>Thirds by X in the acting team's frame.</summary>
    public const double DefensiveThirdEnd = 100.0 / 3;
    public const double AttackingThirdStart = 200.0 / 3;

    /// <summary>The opponent's penalty area in the 0..100 frame: 16.5 m deep, 40.3 m wide.</summary>
    public const double BoxStartX = 100 - 16.5 / LengthMetres * 100;
    public const double BoxMinY = (WidthMetres / 2 - 20.16) / WidthMetres * 100;
    public const double BoxMaxY = 100 - BoxMinY;

    public static double DistanceMetres(PitchPoint a, PitchPoint b)
    {
        double dx = (b.X - a.X) / 100 * LengthMetres;
        double dy = (b.Y - a.Y) / 100 * WidthMetres;
        return Math.Sqrt(dx * dx + dy * dy);
    }

    /// <summary>The same spot seen from the other team's frame.</summary>
    public static PitchPoint Mirror(PitchPoint p) => new(100 - p.X, 100 - p.Y);

    /// <summary>True when a ball-winning event happened in the opponent's defensive third.</summary>
    public static bool IsHighRecovery(MatchEvent e) =>
        e.Type is MatchEventType.Interception or MatchEventType.Tackle &&
        e.Outcome == EventOutcome.Success &&
        e.Start is { } at && at.X >= AttackingThirdStart;
}
